from pathlib import Path
from html.parser import HTMLParser
from decimal import Decimal as D, ROUND_HALF_UP
import json,hashlib,sys
class Page(HTMLParser):
 def __init__(self):
  super().__init__(); self.depth=0; self.parts=[]
 def handle_starttag(self,tag,attrs):
  if tag in ('style','script'): self.depth+=1
 def handle_endtag(self,tag):
  if tag in ('style','script'): self.depth=max(0,self.depth-1)
 def handle_data(self,data):
  if not self.depth: self.parts.append(data)
raw=Path(sys.argv[1]).read_bytes()
page=Page(); page.feed(raw.decode())
visible=' '.join(' '.join(page.parts).split())
quotes=['Platform fee ($0.50 + 5% of total + 1.5% int’l payment)', '+1.5% for international (outside of the US) transactions', '+1.5% for PayPal transactions']
for quote in quotes: assert quote in visible,quote
rows=[]
for gross in map(D,('9','15','25')):
 for route,extra in [('Base only',D('0')),('One surcharge',D('.015')),('Both surcharges',D('.030'))]:
  rate=D('.05')+extra
  fee=(D('.50')+rate*gross).quantize(D('.01'),rounding=ROUND_HALF_UP)
  rows.append(dict(scenario=route,price_usd=str(gross),fee_usd=str(fee),remaining_before_payout_usd=str(gross-fee)))
assert rows[0]['remaining_before_payout_usd']=='8.05'
assert rows[-1]['remaining_before_payout_usd']=='22.50'
out=Path(sys.argv[2]); out.parent.mkdir(parents=True,exist_ok=True)
result=dict(source='https://docs.lemonsqueezy.com/help/getting-started/fees',source_sha256=hashlib.sha256(raw).hexdigest(),quotes=quotes, assumptions='Hypothetical single one-time sale in USD without buyer tax. Cent rounding is modeled. Exchange, payout, refunds and operating costs are excluded. The source example applies the fee to buyer total including VAT. Seller activation, product rights and realized proceeds remain unverified.',rows=rows)
out.write_text(json.dumps(result,indent=2)+'\n')
print(out.read_text())
